I have achieved `export const SessionIdInjector = async () => {
  return {
    "experimental.chat.system.transform": async (hookInput, hookOutput) => {
      if (!hookInput.sessionID) return
      hookOutput.system.push(
        `[Session Context]\nCurrent Session ID: ${hookInput.sessionID}\n[/Session Context]`
      )
    }
  }
`
